import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./Login.css";

const Login = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const handleLogin = async (e) => {
  e.preventDefault();

  try {
    const res = await axios.post(
      "https://medivault-backend-ndak.onrender.com/api/auth/login",
      {
        email,
        password,
      }
    );

    const { token, user } = res.data;

    // Save token and role to localStorage
    localStorage.setItem("token", token);
    localStorage.setItem("role", user.role);

    // Navigate based on role
    if (user.role === "admin") navigate("/dash");
    else if (user.role === "doctor") navigate("/doctor-dashboard");
    else if (user.role === "patient") navigate("/patient-dashboard");
    else navigate("/");

  } catch (err) {
    console.error("Login error:", err);
    alert(err?.response?.data?.message || "Login failed");
  }
};

  return (
    <div className="container">
      {/* Left: Login Section */}
      <div className="login-section">
        <div className="login-card">
          <h2>Login to MediVault</h2>
          <form onSubmit={handleLogin}>
            <input
              type="email"
              placeholder="Email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
            <input
              type="password"
              placeholder="Password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            <button type="submit" className="login-btn">Login</button>
            <div className="links">
              <a href="#">Forgot Password?</a><br />
              Don’t have an account? <a href="/register">Register here</a>
            </div>
          </form>
        </div>
      </div>

      {/* Right: Welcome Section */}
      <div className="welcome-section">
        <div className="welcome-content">
          <h1>Welcome back to <span>MediVault</span></h1>
          <p>Your health, organized and always accessible.</p>
        </div>
        <div className="blob"></div>
        <div className="blob"></div>
        <div className="blob"></div>
      </div>
    </div>
  );
};

export default Login;
